سلام دوستان برنامه نویس.
توی قالب اختصاصیمون ورود/ثبت نام با موبایل و کد تایید داریم. میخوایم کاری کنیم که وقتی کد میاد بتونه autofill بشه. در حد راهنمایی هم که باید سمت کدنویسی چیکار کنیم هم کافیه. سمت پنل پیامکی باید به پترن اینو اضافه کنیم که کردیم:
@farazsms.com #%code%

سلام من از این کد برای مرتب سازی موجودی محصولات یک فروشگا وردپرسی استفاده میکنم . این کد، دوتا مشکل داره

1.	موجودی محصولات رو به جای اینکه، به صورت عددی حساب کنه، میریزه داخل یک آرایه و به همین دلیل نمیتونه به درستی، محصولات رو بر اساس موجودی مرتب کنه 
2.	اگر کد فعال باشه، محصولات جدید اضفه شده رو نشون نمیده. 

add_action('init', function() {
	if( isset($_GET['update_products_arv']) ) {
		$products = wc_get_products( [ 'limit' => 500,'offset' => 200] );
		foreach( $products as $product ){
			$total_stock = $product->get_stock_quantity() ? : 0;
			if( $product->is_type( 'variable' ) ){
				$variations = $product->get_children();
				if( !$variations ) continue;
				foreach ($variations as $variation_id) {
					$variation = wc_get_product( $variation_id );
					$total_stock += $variation->get_stock_quantity() ? : 0;
				}
			}
			update_post_meta($product->get_id(), 'nsaeidi_stock', $total_stock);
		}
	}
});

add_action('woocommerce_product_query', function($q) {
	if( ! is_admin() ) {
		$q->set('orderby', 'meta_value_num');
		$q->set('meta_key', 'nsaeidi_stock');
		$q->set('order', 'DESC');
	}
});

سلام خدمت دوستان گرامی
من یه سایت وردپرسی دارم که چندین سال هست دارم محتوای آموزشی میزارم. بخشی از این محتوا رو محدود کردم و فقط اعضا میتونن ببینن. حالا مشکلی که پیش اومده اینه که محتوای من رو کپی کردند و گوگل به اونا رنک بهتری داده. من کد زیر (با استفاده از شورت کد member) رو برای محدود کردن محتوا استفاده کردم. 
function wpss19_member_check_shortcode( $atts, $content = null ) {
	if ( is_user_logged_in() && !is_null( $content ) && !is_feed() ) {
		return do_shortcode( $content );
	}
	else if ( ( ! is_user_logged_in() ) && !is_null( $content ) && !is_feed() ) {
		return 'این بخش مخصوص اعضای سایت می‌باشد.';
	}
	return '';
}
add_shortcode( 'member', 'wpss19_member_check_shortcode' );

حالا چیزی که میخوام اینه که این کد رو جوری ویرایش کنیم که محتوا برای گوگل و خزنده‌ها و ربات‌هاش که وظیفه ایندکس کردن رو دارند، مخفی نشه و مثل یک کاربر لاگین کرده، محتوا رو ببینه.

